Import ListNotations.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Open Scope bv_scope.

Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

#[local] Abbreviation ASEGS := AsanUbsan.M.loaded_segments.

Definition PATV : Z := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!1,0|^B75f5f5f5f5f5f5f5;").

Section FPX_1. Context {fx : PropExec.FPState}.

#[local] Ltac rwH :=
  repeat match goal with
         | H : getr ?rg ?i = _ |- context [getr ?rg ?i] => rewrite !H
         end.
#[local] Ltac unorm :=
  repeat match goal with
         | |- context [bv_unsigned (Z_to_bv 64 ?z)] =>
             lazymatch z with context [Z_to_bv 64 _] => fail | _ => rewrite (u_Z2bv z) by lia end
         end.
#[local] Ltac wv2 := gres; rwH; unfold at_, v_addi, v_add, v_sub, v_srli, v_slli; imm_norm; unorm; rewrite ?Z.shiftr_div_pow2, ?Z.shiftl_mul_pow2 by lia;
  first [reflexivity | f_equal; lia].

(* [comment removed for export] *)
#[local] Ltac stepsdq F D aa vv oktac :=
  chain_step; [reflexivity
    | eapply step_sd_at with (a := aa) (v := vv); [exact F | reflexivity | exact D | wv2 | gres; rwH; first [reflexivity | f_equal; lia] | oktac]
    | step_simpl].

Section SF5.
  Variable M0 : word -> option byte.
  Variable rom : word -> option byte.
  Variables sp ra : word.
  Variables s F fl sh : Z.
  Variable patv : Z.                     (* [comment removed for export] *)
  #[local] Abbreviation PAT := (word_to_le_bytes 8 (Z_to_bv 64 patv)).
  Hypothesis Hs_def : bv_unsigned sp = s.
  Hypothesis Hret : ret_ok ra.
  Hypothesis Hs : (0x1000000 <= s - 16)%Z /\ (s < 2 ^ 64)%Z.
  Hypothesis Hok : store_ok ASEGS M0 (Z_to_bv 64 (s - 16)) 16%nat = true.
  Hypothesis HG : rt_layout_globs M0.
  Hypothesis Happ : in_app F.
  Hypothesis HF : (0x6c4000 <= F)%Z /\ (F + 2048 <= s - 16 \/ s <= F)%Z.
  Hypothesis Hsh_def : sh = (SB + F / 8)%Z.
  Hypothesis Hfp : rdn ASEGS M0 (Z_to_bv 64 (F + 2040)) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 fl)).
  Hypothesis Hfl : (0x6c4000 <= fl)%Z /\ (fl + 1 < 2 ^ 64)%Z /\ (fl + 1 <= s - 16 \/ s <= fl)%Z.
  Hypothesis Hflok : store_ok ASEGS M0 (Z_to_bv 64 fl) 1%nat = true.
  Hypothesis Hshok : store_ok ASEGS M0 (Z_to_bv 64 sh) 256%nat = true.
  Hypothesis Hshdj : (sh + 256 <= s - 16 \/ s <= sh)%Z.
  (* [comment removed for export] *)
  Hypothesis Hpat : forall M', (forall x : word, (bv_unsigned x < 0x6c4000)%Z -> M' x = M0 x) -> rdn ASEGS M' (0x103a8 : word) 8%nat = Some PAT.

  Definition sf5_M1 (rg : bvmap 5 word) : word -> option byte := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S20!1,2|600;|30;$rg;R!2'1!1,2|21;!1+30!3'4/M0;!2'50!2'6/s;!1,01!2'7}8/ra;").
  Definition sf5_M2 (rg : bvmap 5 word) : word -> option byte := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S50!1,2|21;!1,2|600;|40;|30;!1,03$rg;R!2'10!1+31!3'4!1'8#1!2'51!2'6/s;!1,02!2'7}8!2'9#1!3,:04vv,;!2'<04").
  Definition sf5_M3 (rg : bvmap 5 word) : word -> option byte := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S40!1,2|600;|30;!1,21!1+32$rg;R!2'1!1,2|21;!1+30!3'4!1'=#1!2'50/fl;!3,>3!2'52,?!1,@3").
  Definition sf5_mem (rg : bvmap 5 word) : word -> option byte := ltac2:(Rpl.RP.run_i (rplG ()) 1 "SC0|21;|600;!1,21!1+32|30;!2'7}8!2'52/patv;|40;|48;|500;|508;|510;|518;|608;|610;|618;|620;|628;|630;|638;$rg;R!2'1!1,203&M3;R!1'A#1%~R3!1+B!1+3!1,24!3'4!3'4!3'4!3'4!3'4!3'4!3'4!3'4!3'4!3'4!3'4!3'4!3'4!3'4!3'4!3'4!3'4!3'4!3'4!3'4!3'4!3'4!3'4!3'4!3'4!3'4!3'4!3'4!3'4!3'4!3'4!3'4#1!2'52/sh;5!2'52!2'C/sh;!1,045!2'52!2'C/sh;!1,065!2'52!2'C/sh;!1,075!2'52!2'C/sh;!1,085!2'52!2'C/sh;!1,095!2'52!2'C/sh;!1,0:5!2'52!2'C/sh;!1,0;5!2'52!2'C/sh;!1,015!2'52!2'C/sh;!1,0<5!2'52!2'C/sh;!1,0=5!2'52!2'C/sh;!1,0>5!2'52!2'C/sh;!1,0?5!2'52!2'C/sh;!1,0@5!2'52!2'C/sh;!1,0A5!2'52!2'C/sh;!1,0B5!2'52!2'C/sh;!1,0|700;5!2'52!2'C/sh;!1,0|708;5!2'52!2'C/sh;!1,0|710;5!2'52!2'C/sh;!1,0|718;5!2'52!2'C/sh;!1,0|720;5!2'52!2'C/sh;!1,0|728;5!2'52!2'C/sh;!1,0|730;5!2'52!2'C/sh;!1,0|738;5!2'52!2'C/sh;!1,0|740;5!2'52!2'C/sh;!1,0|748;5!2'52!2'C/sh;!1,0|750;5!2'52!2'C/sh;!1,0|758;5!2'52!2'C/sh;!1,0|760;5!2'52!2'C/sh;!1,0|768;5!2'52!2'C/sh;!1,0|770;5!2'52!2'C/sh;!1,0|778;5").

  Lemma sp_sf5 : sp = Z_to_bv 64 s.  Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S30!1,2|600;!2'F0/sp;!1+30!6'D+E1$s;R+E!3+G2/sp;!2'50#1!4'H2!2'501/sp;!2'I0/sp;/s;/Hs_def;").
Qed.

  Theorem sfree5_run : forall regs,
    getr regs 10 = Z_to_bv 64 F -> getr regs 2 = sp -> getr regs 1 = ra ->
    exists regs',
